{
  "variables": [
    {"name": "donor", "domain": ["donor1", "donor2", "donor3", "donor4", "donor5"]},
    {"name": "neuron", "domain": ["neuron1", "neuron2", "neuron3", "neuron4", "neuron5"]},
    {"name": "epigenetic_silencing", "domain": [True, False]},
    {"name": "lipid_accumulation", "continuous": true, "lower": null, "upper": null}
  ],
  "scope": "donor in ('donor1', 'donor2', 'donor3', 'donor4', 'donor5) and neuron in ('neuron1', 'neuron2', 'neuron3', 'neuron4', 'neuron5')",
  "assumptions": [
    "epigenetic_silencing == True or epigenetic_silencing == False",
    "lipid_accumulation >= 0"
  ],
  "claims": [
    "epigenetic_silencing == True implies lipid_accumulation > lipid_accumulation where epigenetic_silencing == False"
  ],
  "alternatives": [
    "Lipid accumulation is not affected by epigenetic silencing of the repressor gene."
  ]
}

{
  "variables": [
    {"name": "autophagy_flux_knockout", "continuous": true, "lower": null, "upper": null},
    {"name": "autophagy_flux_control", "continuous": true, "lower": null, "upper": null},
    {"name": "barrier_integrity_knockout", "continuous": true, "lower": null, "upper": null},
    {"name": "barrier_integrity_control", "continuous": true, "lower": null, "upper": null}
  ],
  "scope": null,
  "assumptions": [
    "autophagy_flux_knockout < autophagy_flux_control",
    "barrier_integrity_knockout <= barrier_integrity_control"
  ],
  "claims": [
    "not (autophagy_flux_knockout < autophagy_flux_control) or (barrier_integrity_knockout <= barrier_integrity_control)"
  ],
  "alternatives": [
    "No significant difference in barrier integrity between knockout and control mice",
    "Barrier integrity improves or remains unchanged despite impaired autophagy flux"
  ]
}

{
  "variables": [
    {"name": "age", "continuous": true, "lower": null, "upper": null},
    {"name": "frailty_index", "continuous": true, "lower": 0, "upper": 1},
    {"name": "in_hospital_mortality", "domain": [0, 1]},
    {"name": "admission_condition", "domain": ["pneumonia", "other"]}
  ],
  "scope": "admission_condition == 'pneumonia'",
  "assumptions": [
    "frailty_index >= 0",
    "frailty_index <= 1",
    "in_hospital_mortality in (0, 1)"
  ],
  "claims": [
    "frailty_index > 0.5 implies in_hospital_mortality > 0.5"
  ],
  "alternatives": [
    "No significant difference in in-hospital mortality rates between patients with high and low frailty index scores."
  ]
}

{
  "variables": [
    {"name": "participant", "domain": ["participant1", "participant2", "participant3", "participant4", "participant5"]},
    {"name": "time", "continuous": true, "lower": 0, "upper": 5},
    {"name": "plasma_proteomic_signature", "domain": ["signature1", "signature2", "signature3", "signature4", "signature5"]},
    {"name": "frailty_status", "domain": ["frail", "not frail"]}
  ],
  "scope": "participant in ('participant1', 'participant2', 'participant3', 'participant4', 'participant5') and time >= 0 and time <= 5",
  "assumptions": [
    "plasma_proteomic_signature in ('signature1', 'signature2', 'signature3', 'signature4', 'signature5')",
    "frailty_status in ('frail', 'not frail')"
  ],
  "claims": [
    "not (plasma_proteomic_signature == 'signature1' and frailty_status == 'frail') or (plasma_proteomic_signature == 'signature1' and frailty_status == 'not frail')",
    "not (plasma_proteomic_signature == 'signature2' and frailty_status == 'frail') or (plasma_proteomic_signature == 'signature2' and frailty_status == 'not frail')",
    "not (plasma_proteomic_signature == 'signature3' and frailty_status == 'frail') or (plasma_proteomic_signature == 'signature3' and frailty_status == 'not frail')",
    "not (plasma_proteomic_signature == 'signature4' and frailty_status == 'frail') or (plasma_proteomic_signature == 'signature4' and frailty_status == 'not frail')",
    "not (plasma_proteomic_signature == 'signature5' and frailty_status == 'frail') or (plasma_proteomic_signature == 'signature5' and frailty_status == 'not frail')"
  ],
  "alternatives": [
    "No significant correlation between plasma proteomic signatures and frailty progression"
  ]
}

{
  "variables": [
    {"name": "plasma_abundance", "continuous": true, "lower": 0, "upper": null},
    {"name": "time_to_resistance", "continuous": true, "lower": 0, "upper": null}
  ],
  "scope": null,
  "assumptions": [],
  "claims": ["plasma_abundance > x and time_to_resistance < y for all x, y where plasma_abundance > x and time_to_resistance < y"],
  "alternatives": ["If patients with lower plasma abundance of the target protein develop resistance to their medication more quickly than those with higher plasma abundance"]
}

{
  "variables": [
    {"name": "sample", "domain": ["post-mortem brain samples"]},
