    {"name": "lipid_accumulation", "continuous": true, "lower": 0, "upper": null}
  ],
  "scope": "sample in ['post-mortem brain samples']",
  "assumptions": [],
  "claims": ["aberrant_splicing > 0 and lipid_accumulation > 0"],
  "alternatives": ["No significant correlation between aberrant splicing and lipid accumulation"]
}

{
  "variables": [
    {"name": "autophagy_flux", "continuous": true, "lower": null, "upper": null},
    {"name": "cell_death_rate", "continuous": true, "lower": null, "upper": null}
  ],
  "scope": null,
  "assumptions": [],
  "claims": [
    "autophagy_flux < 0 or cell_death_rate > 0"
  ],
  "alternatives": []
}

{
  "variables": [
    {"name": "age_group", "domain": ["older_adults"]},
    {"name": "antibiotic_exposure", "domain": [true, false]},
    {"name": "time_of_exposure", "domain": ["first_week"]},
    {"name": "functional_decline", "continuous": true, "lower": null, "upper": null},
    {"name": "time_of_measurement", "domain": ["six_months"]}
  ],
  "scope": "(age_group == 'older_adults') and (time_of_measurement == 'six_months')",
  "assumptions": [
    "(antibiotic_exposure == true) and (time_of_exposure == 'first_week')",
    "(antibiotic_exposure == false) and (time_of_exposure == 'first_week')"
  ],
  "claims": [
    "not (antibiotic_exposure) or (functional_decline > 0)",
    "(antibiotic_exposure) and (functional_decline > 0)"
  ],
  "alternatives": [
    "No significant difference in functional decline at six months between exposed and non-exposed older adults"
  ]
}

{
  "variables": [
    {"name": "mouse", "domain": ["knockout", "wild-type"]},
    {"name": "mtDNA_copy_number", "continuous": true, "lower": null, "upper": null},
    {"name": "neuronal_firing_efficiency", "continuous": true, "lower": null, "upper": null}
  ],
  "scope": "(mouse == 'knockout')",
  "assumptions": [
    "mtDNA_copy_number < 0 or neuronal_firing_efficiency < 0",
    "mtDNA_copy_number > 0 or neuronal_firing_efficiency > 0"
  ],
  "claims": [
    "not (mouse == 'knockout') or (mtDNA_copy_number < 0 and neuronal_firing_efficiency > 0)"
  ],
  "alternatives": [
    "no significant correlation between mtDNA copy number and neuronal firing rates in knockout mice",
    "normal neuronal firing rates despite reduced mtDNA copy numbers"
  ]
}

{
  "variables": [
    {"name": "mtDNA_copy_number", "continuous": true, "lower": 0, "upper": null},
    {"name": "barrier_integrity", "continuous": true, "lower": 0, "upper": null}
  ],
  "scope": null,
  "assumptions": [],
  "claims": ["not (mtDNA_copy_number == barrier_integrity)"],
  "alternatives": ["an increase in mtDNA copy number is associated with higher barrier integrity", "no significant correlation between mtDNA copy number and barrier integrity"]
}

{
  "variables": [
    {"name": "age_group", "domain": ["older_adults"]},
    {"name": "time_period", "continuous": true, "lower": 0, "upper": 5},
    {"name": "metabolite_level", "continuous": true, "lower": null, "upper": null},
    {"name": "diabetes_status", "domain": ["develops_type_2_diabetes", "does_not_develop_type_2_diabetes"]}
  ],
  "scope": "(age_group == 'older_adults')",
  "assumptions": [
    "time_period <= 5",
    "metabolite_level is a real number",
    "diabetes_status in ('develops_type_2_diabetes', 'does_not_develop_type_2_diabetes')"
  ],
  "claims": [
    "metabolite_level != 'does_not_develop_type_2_diabetes' or (diabetes_status == 'develops_type_2_diabetes')"
  ],
  "alternatives": [
    "Serum metabolite levels do not predict the onset of type 2 diabetes in older adults."
  ]
}

{
  "variables": [
    {"name": "patient", "domain": ["adults_admitted_with_pneumonia"]},
    {"name": "urine_output", "continuous": true, "lower": null, "upper": null},
    {"name": "readmission", "domain": [true, false]},
    {"name": "time_period", "domain": ["first_24_hours", "30_days"]}
  ],
  "scope": "patient in ('adults_admitted_with_pneumonia')",
  "assumptions": [
    "urine_output > median(urine_output) if time_period == 'first_24_hours'",
    "urine_output <= median(urine_output) if time_period == 'first_24_hours'"
  ],
  "claims": [
    "not (urine_output > median(urine_output) if time_period == 'first_24_hours')) or (readmission == false if time_period == '30_days'))",
    "not (urine_output <= median(urine_output) if time_period == 'first_24_hours')) or (readmission == true if time_period == '30_days'))"
  ],
  "alternatives": [
    "Similar or higher 30-day readmission rates in the group with higher urine output"
  ]
}

{
  "variables": [
    {"name": "mouse", "domain": ["knockout_mouse_with_aberrant_splicing", "knockout_mouse_with_normal_splicing"]},
    {"name": "cell_death_rate", "continuous": true, "lower": 0, "upper": null}
  ],
  "scope": "mouse in ('knockout_mouse_with_aberrant_splicing', 'knockout_mouse_with_normal_splicing')",
  "assumptions": [
    "mouse in ('knockout_mouse_with_aberrant_splicing', 'knockout_mouse_with_normal_splicing')"
  ],
  "claims": [
    "not (mouse == 'knockout_mouse_with_aberrant_splicing') or (cell_death_rate > cell_death_rate[mouse == 'knockout_mouse_with_normal_splicing'])"
  ],
  "alternatives": [
    "Aberrant splicing does not affect cell death rate"
  ]
}

{
  "variables": [
    {"name": "mouse", "domain": ["knockout_mouse"]},
    {"name": "mtDNA_copy_number", "continuous": true, "lower": null, "upper": null},
    {"name": "fibrosis_score", "continuous": true, "lower": null, "upper": null}
  ],
  "scope": "(mouse == 'knockout_mouse')",
  "assumptions": [],
  "claims": ["(mtDNA_copy_number == fibrosis_score) or (mtDNA_copy_number != fibrosis_score)"],
