{
  "variables": [
    {"name": "degree_of_epigenetic_silencing", "continuous": true, "lower": 0, "upper": null},
    {"name": "fibrosis_score", "continuous": true, "lower": 0, "upper": null}
  ],
  "scope": null,
  "assumptions": [],
  "claims": [
