    "risk_score >= 0",
    "incidence >= 0"
  ],
  "claims": [
    "risk_score > risk_score2 implies incidence > incidence2"
  ],
  "alternatives": [
    "No significant correlation between polygenic risk score and incidence of cardiovascular disease"
  ]
}

{
  "variables": [
    {"name": "patient", "domain": ["with_variant", "without_variant"]},
    {"name": "toxicity_level", "domain": ["grade_3_or_higher", "grade_2_or_lower"]}
  ],
  "scope": "patient in ('with_variant', 'without_variant')",
  "assumptions": [
    "toxicity_level in ('grade_3_or_higher', 'grade_2_or_lower')"
  ],
  "claims": [
    "not (patient == 'with_variant') or (toxicity_level == 'grade_3_or_higher')"
  ],
  "alternatives": [
    "The genetic variant does not influence the toxicity level."
  ]
}

{
  "variables": [
    {"name": "patient", "domain": ["type_2_diabetes_with_variant", "type_2_diabetes_without_variant"]},
    {"name": "survival_time", "continuous": true, "lower": 0, "upper": null}
  ],
