  "assumptions": [
    "survival_time >= 0"
  ],
  "claims": [
    "not (patient == 'type_2_diabetes_with_variant') or (survival_time < survival_time[patient == 'type_2_diabetes_without_variant'])"
  ],
  "alternatives": [
    "No significant difference in overall survival time between patients with and without the genetic variant"
  ]
}

{
  "variables": [
    {"name": "prs", "continuous": true, "lower": null, "upper": null},
    {"name": "diabetes_incidence", "continuous": true, "lower": 0, "upper": 1}
  ],
  "scope": "(prs is not None) and (diabetes_incidence is not None)",
